    {
      "id": "ai-toolkit",
      "title": "AI toolkit capabilities and testing",
      "claims": [
        {
          "text": "AI models are not inherently intelligent; their complex abilities come from toolkits and ready-made solutions.",
          "evidence": [1]
        },
        {
          "text": "There is no demand for truly intelligent AI because people themselves lack understanding.",
          "evidence": [2]
        },
        {
          "text": "Testing AI from 2022‑2023 with modern toolkits like Opencode may reveal limitations due to small context windows of older models.",
          "evidence": [3]
        },
        {
          "text": "InstinctGPT compares ~3B and GPT‑3 175B models with external runtimes and tools, showing toolkits boost performance but cannot compensate for core model ability deficits.",
          "evidence": [8]
        },
        {
          "text": "Older models were trained on everything without clear purpose; modern models aim to squeeze more from fewer parameters and are sometimes fine‑tuned for specific tasks.",
          "evidence": [14]
        }
      ]
    },
    {
